import { CATEGORIES } from './questions.js';
import { validateDatabase,validateConfig,poolFor,newGame,reveal,expire,grade,next,canUndo,undo,scores,winners,restore,byId } from './logic.js';
const $=s=>document.querySelector(s), app=$('#app');
const GAME='chaos.game.v1', SETTINGS='chaos.settings.v1';
let config={names:['Gracz 1','Gracz 2'],seconds:5,rounds:5,categories:['c1','c2','c4','c5'],muted:false};
let game=null, saved=null, screen='setup', raf=0, audio=null, startTime=0, wallStart=0, lastBeep=-1, interrupted=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(s){$('#notice').textContent=s;$('#notice').hidden=false;}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{notice('Nie można zapisać danych. Gra działa, ale po zamknięciu strony postęp może zniknąć.');return false;}}
function persist(){if(game)write(GAME,game);}
function settings(){write(SETTINGS,config);}
function clearSaved(){try{localStorage.removeItem(GAME);return true;}catch{notice('Nie udało się usunąć zapisu. Sprawdź ustawienia pamięci przeglądarki.');return false;}}
function syncMute(){const muted=game?game.config.muted:config.muted;$('#mute').textContent=`DŹWIĘK: ${muted?'WYŁ.':'WŁ.'}`;$('#mute').setAttribute('aria-pressed',String(muted));$('#mute').setAttribute('aria-label',muted?'Włącz dźwięki':'Wycisz dźwięki');}
function unlockAudio(){if((game?.config||config).muted)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audio??=new Audio();audio.resume().catch(()=>{});}catch{}}
function beep(final=false){if((game?.config||config).muted||!audio||audio.state!=='running')return;try{const o=audio.createOscillator(),v=audio.createGain();o.connect(v);v.connect(audio.destination);o.frequency.value=final?220:700;v.gain.setValueAtTime(.09,audio.currentTime);v.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.start();o.stop(audio.currentTime+.2);}catch{}}
$('#mute').onclick=()=>{const c=game?game.config:config;c.muted=!c.muted;config.muted=c.muted;settings();persist();syncMute();if(!c.muted)unlockAudio();};
function show(html){app.innerHTML=html;syncMute();}
function focusMain(){app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
const symbols=['↯','◈','♡','⌘','☠','✳'],colors=['#d5ff5f','#b9a0ff','#ff9775','#9bd4e5','#e4cda0','#f4a6d7'];
function renderSetup(){
 screen='setup';game=null;
 show(`<section class="intro"><div><div class="eyebrow">GRA IMPREZOWA · 1–10 GRACZY</div><h1>5 sekund.<br><em>Totalny chaos.</em></h1><p>Trzy odpowiedzi. Jeden oddech. I nagle zapominasz, jak nazywa się wszystko.</p></div><div class="stamp" aria-hidden="true"><strong>5</strong><span>SEKUND NA WSZYSTKO</span></div></section>
 <div class="rule-strip"><span><b>01</b> Przekaż telefon</span><span><b>02</b> Wymień 3 rzeczy</span><span><b>03</b> Zgarnij punkt</span></div>
 <section class="setup" aria-label="Konfiguracja gry"><div class="panel"><div class="panel-title"><h3><span class="step">01</span> Kto gra?</h3><div class="player-control"><button id="minus" aria-label="Usuń ostatniego gracza">−</button><span id="count">${config.names.length}</span><button id="plus" aria-label="Dodaj gracza">+</button></div></div>
 <div class="names">${config.names.map((n,i)=>`<label class="name-row"><span>${String(i+1).padStart(2,'0')}</span><input data-name="${i}" aria-label="Imię gracza ${i+1}" maxlength="40" value="${esc(n)}" autocomplete="off"></label>`).join('')}</div>
 <div class="setting"><div class="setting-label"><span>Czas na odpowiedź</span><span>sekundy</span></div><div class="choices">${[5,6,7,8,9,10].map(n=>`<button data-seconds="${n}" aria-pressed="${config.seconds===n}" class="${config.seconds===n?'selected':''}">${n} s</button>`).join('')}</div></div>
 <div class="setting"><div class="setting-label"><span>Pytania na gracza</span><span id="limit"></span></div><div class="choices">${[5,10,15,20].map(n=>`<button data-rounds="${n}" aria-pressed="${config.rounds===n}" class="${config.rounds===n?'selected':''}">${n}</button>`).join('')}<button id="custom" class="${![5,10,15,20].includes(config.rounds)?'selected':''}">Własna</button></div><label id="custom-wrap" ${[5,10,15,20].includes(config.rounds)?'hidden':''}><span class="hint">Własna liczba pytań na gracza</span><input class="custom-input" id="custom-rounds" type="number" min="1" step="1" value="${config.rounds}" inputmode="numeric"></label></div></div>
 <div class="panel"><div class="panel-title"><h3><span class="step">02</span> Wybierz swój chaos</h3><span class="tag">300 PYTAŃ</span></div><div class="category-grid">${CATEGORIES.map((c,i)=>`<label class="category" style="--cat:${colors[i]}"><input type="checkbox" data-category="${c.id}" ${config.categories.includes(c.id)?'checked':''}><span class="symbol" aria-hidden="true">${symbols[i]}</span><strong>${esc(c.name)}${c.adult?'<span class="adult">18+</span>':''}</strong><small>50 pytań</small></label>`).join('')}</div><p class="hint">Mieszaj kategorie do woli. Każde pytanie pojawi się tylko raz w tej rozgrywce. Kategoria 18+ zawiera treści dla dorosłych; „Totalny chaos” również zawiera dorosły humor.</p></div></section>
 <div class="summary"><div class="summary-text"><strong id="summary"></strong><small id="summary-detail"></small><p id="error" class="error" role="status"></p></div><button id="start" class="primary">ZACZYNAMY CHAOS <span class="arrow">↗</span></button></div>
 <details class="help"><summary>Jak grać i zainstalować grę?</summary><p>Odkryj pytanie i wymień 3 rzeczy przed końcem czasu. Pozostali gracze oceniają odpowiedź: trzy zaakceptowane odpowiedzi to 1 punkt, bez punktów częściowych. Solo oceniasz się samodzielnie. Ocenę można cofnąć do odkrycia następnego pytania. Ukrycie strony kończy odliczanie.</p><p>Na iPhonie otwórz grę w Safari → Udostępnij → Do ekranu początkowego. Offline działa po pobraniu zasobów przez HTTPS (lub na localhost), nie przez file://. Zapis pozostaje w tej przeglądarce.</p></details>`);
 $('#minus').disabled=config.names.length===1;$('#plus').disabled=config.names.length===10;
 $('#plus').onclick=()=>{let i=config.names.length+1;while(config.names.some(n=>n.trim().toLowerCase()===`gracz ${i}`))i++;config.names.push(`Gracz ${i}`);settings();renderSetup();};
 $('#minus').onclick=()=>{config.names.pop();settings();renderSetup();};
 document.querySelectorAll('[data-name]').forEach(el=>el.oninput=()=>{config.names[+el.dataset.name]=el.value;settings();updateSummary();});
 document.querySelectorAll('[data-seconds]').forEach(el=>el.onclick=()=>{config.seconds=+el.dataset.seconds;settings();renderSetup();});
 document.querySelectorAll('[data-rounds]').forEach(el=>el.onclick=()=>{config.rounds=+el.dataset.rounds;settings();renderSetup();});
 $('#custom').onclick=()=>{$('#custom-wrap').hidden=false;$('#custom-rounds').focus();};
 $('#custom-rounds').oninput=e=>{config.rounds=Number(e.target.value);settings();updateSummary();document.querySelectorAll('[data-rounds]').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false');});$('#custom').classList.add('selected');};
 document.querySelectorAll('[data-category]').forEach(el=>el.onchange=()=>{config.categories=[...document.querySelectorAll('[data-category]:checked')].map(e=>e.dataset.category);settings();updateSummary();});
 $('#start').onclick=()=>{try{game=newGame(config);saved=null;interrupted=false;screen='game';settings();persist();renderGame();focusMain();}catch(e){$('#error').textContent=e.message;}};
 updateSummary();
}
function updateSummary(){const pool=poolFor(config.categories).length,max=Math.floor(pool/config.names.length);$('#limit').textContent=`maks. ${max}`;$('#custom-rounds').max=max;$('#summary').textContent=`${config.names.length} graczy · ${config.seconds} sekund · ${config.rounds} pytań na osobę`;$('#summary-detail').textContent=`${config.names.length*config.rounds} tur łącznie / ${pool} dostępnych pytań · bez powtórek`;try{validateConfig(config);$('#error').textContent='';$('#start').disabled=false;}catch(e){$('#error').textContent=e.message;$('#start').disabled=true;}}
function scoreTable(){return `<section class="scoreboard"><h3>Tablica wyników</h3><div class="table-wrap"><table><thead><tr><th scope="col">Gracz</th><th scope="col">Punkty</th><th scope="col">Rozegrane</th><th scope="col">Pozostałe</th></tr></thead><tbody>${scores(game).map(r=>`<tr><td>${esc(r.name)}</td><td><strong>${r.points}</strong></td><td>${r.played}</td><td>${r.remaining}</td></tr>`).join('')}</tbody></table></div></section>`;}
function renderGame(){
 screen='game';const g=game,i=g.cursor%g.config.names.length,player=scores(g)[i],round=Math.floor(g.cursor/g.config.names.length)+1,q=byId.get(g.queue[g.cursor]);
 if(g.stage==='finished'){renderResults();return;}
 let card='';
 if(g.stage==='handoff')card=`<div class="eyebrow">PRZEKAŻ TELEFON</div><div class="covered" aria-hidden="true">↯</div><h2>${esc(player.name)}, Twoja kolej.</h2><p>Tura ${round} z ${g.config.rounds} · ${player.points} pkt<br>Pytanie czeka. Weź oddech.</p><button id="reveal" class="primary wide">ODKRYJ PYTANIE ↗</button>`;
 else if(g.stage==='reviewed'){const accepted=g.history.at(-1).accepted;card=`<div class="eyebrow">OCENA ZAPISANA</div><div class="winner">${accepted?'+1':'0'}</div><h2>${accepted?'Zaliczone!':'Następnym razem!'}</h2><p>${esc(player.name)} · ${player.points} pkt</p><button id="next" class="primary wide">NASTĘPNY GRACZ ↗</button>`;}
 else card=`<div class="eyebrow">${esc(CATEGORIES.find(c=>c.id===q.category).name)}</div><p class="question" style="color:var(--ink)">${esc(q.text)}</p>${g.stage==='running'?`<div id="timer" class="timer" role="timer" aria-label="Pozostały czas">${g.config.seconds.toFixed(1)}</div><p>Wymień 3 rzeczy. Czas ucieka!</p>`:`<div class="time-up" role="status">KONIEC CZASU</div>${interrupted?'<p class="pause-info">Odliczanie zostało przerwane — czas upłynął.</p>':''}<p>Trzy odpowiedzi w limicie? Gracze decydują.</p><div class="grading"><button id="yes" class="primary">ZALICZONE +1</button><button id="no" class="reject">NIEZALICZONE 0</button></div>`}`;
 show(`<section class="game"><div class="game-top"><span>RUNDA ${round} / ${g.config.rounds}</span><span>${g.history.length} / ${g.queue.length} OCENIONYCH TUR</span></div><div class="progress" aria-hidden="true"><span style="width:${100*g.history.length/g.queue.length}%"></span></div><div class="turn-card">${card}</div><div class="actions">${canUndo(g)?'<button id="undo" class="secondary">↶ Cofnij ostatnią ocenę</button>':''}<button id="exit" class="secondary">Nowa konfiguracja</button></div>${scoreTable()}</section>`);
 if($('#reveal'))$('#reveal').onclick=()=>{unlockAudio();if(!reveal(g))return;interrupted=false;startTime=performance.now();wallStart=Date.now();lastBeep=-1;persist();renderGame();raf=requestAnimationFrame(tick);};
 if($('#yes'))$('#yes').onclick=()=>onGrade(true);
 if($('#no'))$('#no').onclick=()=>onGrade(false);
 if($('#next'))$('#next').onclick=()=>{if(next(g)){persist();renderGame();focusMain();}};
 bindActions();
}
function onGrade(value){if(grade(game,value)){persist();renderGame();focusMain();}}
function tick(now){if(!game||game.stage!=='running')return;const left=game.config.seconds-Math.max(now-startTime,Date.now()-wallStart)/1000;if(left<=0){endTimer(false);return;}const el=$('#timer');if(el){el.textContent=left.toFixed(1);el.classList.toggle('urgent',left<=3);}const s=Math.ceil(left);if(s<=3&&s!==lastBeep){lastBeep=s;beep();}raf=requestAnimationFrame(tick);}
function endTimer(wasInterrupted){cancelAnimationFrame(raf);if(!game||!expire(game))return;interrupted=wasInterrupted;persist();if(!wasInterrupted){beep(true);if(!game.config.muted&&navigator.vibrate)navigator.vibrate(180);}renderGame();}
function bindActions(){if($('#undo'))$('#undo').onclick=()=>{if(undo(game)){interrupted=false;persist();renderGame();focusMain();}};if($('#exit'))$('#exit').onclick=discard;}
function discard(){if(!confirm('Usunąć zapisaną rozgrywkę i przejść do konfiguracji?'))return;if(!clearSaved())return;cancelAnimationFrame(raf);if(game)config={...game.config,names:[...game.config.names],categories:[...game.config.categories]};saved=null;game=null;renderSetup();focusMain();}
function renderResults(){const rows=scores(game).sort((a,b)=>b.points-a.points),win=winners(game);show(`<section class="game"><div class="turn-card"><div class="eyebrow">KONIEC GRY · ${game.queue.length} TUR</div><div class="confetti" aria-hidden="true">✦ ✳ ✦</div><h2>${win.length>1?'Mamy remis!':'Mamy zwycięzcę!'}</h2><p style="color:var(--acid);font-size:23px;font-weight:bold">${win.map(w=>esc(w.name)).join(' · ')}</p><div class="ranking">${rows.map(r=>`<div class="ranking-row"><span>${1+rows.filter(x=>x.points>r.points).length}. ${esc(r.name)}</span><span><b>${r.points} pkt</b><small>${r.percent}% poprawnych</small></span></div>`).join('')}</div><button id="again" class="primary wide">ZAGRAJ PONOWNIE ↗</button></div><div class="actions">${canUndo(game)?'<button id="undo" class="secondary">↶ Cofnij ostatnią ocenę</button>':''}<button id="exit" class="secondary">Nowa konfiguracja</button></div>${scoreTable()}</section>`);$('#again').onclick=()=>{if(!confirm('Zastąpić zakończoną grę nową rozgrywką z tymi samymi ustawieniami?'))return;game=newGame(game.config);interrupted=false;persist();renderGame();focusMain();};bindActions();}
function renderResume(){screen='resume';show(`<section class="resume"><div class="eyebrow">CHAOS JESZCZE SIĘ NIE SKOŃCZYŁ</div><h2 style="margin-top:20px">Wracamy do gry?</h2><p>Znaleziono zapis: ${saved.config.names.map(esc).join(', ')}.<br>Ocenione tury: ${saved.history.length} z ${saved.queue.length}. ${saved.stage==='finished'?'Rozgrywka jest zakończona — możesz wrócić do wyników.':'Kolejka pytań i punkty są zachowane.'}</p><div class="actions" style="justify-content:flex-start"><button id="continue" class="primary">KONTYNUUJ ↗</button><button id="discard" class="secondary">Usuń zapis i zacznij od nowa</button></div></section>`);$('#continue').onclick=()=>{game=saved;saved=null;config=game.config;interrupted=game.stage==='judging';persist();renderGame();focusMain();};$('#discard').onclick=discard;}
// Ukrycie lub opuszczenie strony kończy aktywny timer; zapis "running" też odzyskujemy jako "judging".
document.addEventListener('visibilitychange',()=>{if(document.hidden)endTimer(true);});
window.addEventListener('pagehide',()=>endTimer(true));
window.addEventListener('pageshow',e=>{if(e.persisted)endTimer(true);});
try{validateDatabase();try{const s=localStorage.getItem(SETTINGS);if(s){const parsed=JSON.parse(s);config=validateConfig(parsed);}}catch{notice('Ustawienia były nieprawidłowe lub niedostępne. Przywrócono ustawienia domyślne.');}try{const raw=localStorage.getItem(GAME);if(raw)saved=restore(raw);}catch{notice('Zapis jest nieprawidłowy lub niedostępny. Nie został wczytany. Nowa gra zastąpi go dopiero po starcie.');}if(saved)renderResume();else renderSetup();}catch(e){show(`<section class="resume"><h2>Nie udało się uruchomić gry</h2><p>${esc(e.message)}</p></section>`);}
if('serviceWorker' in navigator && ['https:','http:'].includes(location.protocol)){
 navigator.serviceWorker.register('./sw.js').then(async reg=>{const ready=await navigator.serviceWorker.ready;if(ready.active)$('#offline').textContent='GOTOWE OFFLINE';reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)notice('Aktualizacja gry jest gotowa. Zostanie użyta po zamknięciu wszystkich kart gry.');});});}).catch(()=>{$('#offline').textContent='OFFLINE NIEDOSTĘPNE';notice('Nie udało się pobrać plików offline. Gra działa w trybie online.');});
}
